package com.northstarbank.console.domain;import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="service_requests") public class ServiceRequest{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)public Long id;public String customerId;public String type;public String raisingStaff;public String owningBranch;public String assignedTo;public String status;@Column(length=2000)public String notes;@Column(length=2000)public String resolution;public Instant createdAt=Instant.now();protected ServiceRequest(){}public ServiceRequest(String c,String t,String s,String b,String notes){customerId=c;type=t;raisingStaff=s;owningBranch=b;status="open";this.notes=notes;}}
